import { writeFile, mkdir, unlink } from 'fs/promises';
import { join } from 'path';

export interface UploadedFile {
  /** URL-accessible path stored in the DB and used by next/image, e.g. /uploads/{reportId}/{name} */
  storagePath: string;
}

/**
 * Uploads a single file and returns its storagePath.
 *
 * The storageName must be pre-generated by the caller (so the DB record
 * and the file on disk share the same name even if upload happens after insert).
 *
 * STORAGE_PROVIDER=local  → writes to public/uploads/{reportId}/ (dev / self-hosted)
 * STORAGE_PROVIDER=azure  → upload to Azure Blob Storage (production)
 */
export async function uploadAttachment(
  file: File,
  reportId: number | string,
  storageName: string,
): Promise<UploadedFile> {
  const provider = process.env.STORAGE_PROVIDER ?? 'local';

  if (provider === 'azure') {
    return uploadToAzure(file, reportId, storageName);
  }

  return uploadToLocal(file, reportId, storageName);
}

async function uploadToLocal(file: File, reportId: number | string, storageName: string): Promise<UploadedFile> {
  const uploadDir = join(process.cwd(), 'public', 'uploads', String(reportId));
  await mkdir(uploadDir, { recursive: true });
  const buffer = Buffer.from(await file.arrayBuffer());
  await writeFile(join(uploadDir, storageName), buffer);
  return {
    storagePath: `/uploads/${String(reportId)}/${storageName}`,
  };
}

async function uploadToAzure(file: File, reportId: number | string, storageName: string): Promise<UploadedFile> {
  const container = await getAzureContainerClient();
  const blobClient = container.getBlockBlobClient(`${String(reportId)}/${storageName}`);
  const buffer = Buffer.from(await file.arrayBuffer());
  await blobClient.uploadData(buffer, {
    blobHTTPHeaders: { blobContentType: file.type },
  });
  // The full blob URL is stored in the DB and rendered directly by next/image
  // (the container has anonymous blob read; the account host is allow-listed in next.config.ts).
  return { storagePath: blobClient.url };
}

async function deleteFromAzure(storagePath: string): Promise<void> {
  const container = await getAzureContainerClient();
  // storagePath is the full blob URL — the blob name is the path after "/{container}/".
  const { pathname } = new URL(storagePath);
  const marker = `/${container.containerName}/`;
  const idx = pathname.indexOf(marker);
  const blobName = decodeURIComponent(idx >= 0 ? pathname.slice(idx + marker.length) : pathname.replace(/^\//, ''));
  await container.getBlockBlobClient(blobName).deleteIfExists();
}

/** Builds a container client from the connection-string env vars (validated at startup by env.ts). */
async function getAzureContainerClient() {
  const connectionString = process.env.AZURE_STORAGE_CONNECTION_STRING;
  const containerName = process.env.AZURE_STORAGE_CONTAINER;
  if (!connectionString || !containerName) {
    throw new Error(
      'AZURE_STORAGE_CONNECTION_STRING and AZURE_STORAGE_CONTAINER are required when STORAGE_PROVIDER=azure.',
    );
  }
  const { BlobServiceClient } = await import('@azure/storage-blob');
  return BlobServiceClient.fromConnectionString(connectionString).getContainerClient(containerName);
}

/**
 * Deletes an attachment file from storage.
 *
 * storagePath is the value stored in the DB, e.g. /uploads/42/abc.jpg
 * For local storage, this maps to public/uploads/42/abc.jpg on disk.
 * Silently ignores missing files (ENOENT) to keep deletions idempotent.
 */
export async function deleteAttachment(storagePath: string): Promise<void> {
  const provider = process.env.STORAGE_PROVIDER ?? 'local';

  if (provider === 'azure') {
    await deleteFromAzure(storagePath);
    return;
  }

  // storagePath starts with "/" — strip it before joining with cwd
  const relativePath = storagePath.startsWith('/') ? storagePath.slice(1) : storagePath;
  const fullPath = join(process.cwd(), 'public', relativePath);
  await unlink(fullPath).catch((err: NodeJS.ErrnoException) => {
    if (err.code !== 'ENOENT') throw err;
  });
}
